package nl.smartstreamlabs.sbwdroneconfig;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DwfBudgetFairnessTest{
 @Test void perKindCapsDoNotStarveMachinesWhenTotalBudgetIsLarger(){var work=new DwfWorkBudget();int[]seen=new int[200];for(int i=0;i<seen.length;i++){final int n=i;work.add(new DwfWorkBudget.Job(){public DwfWorkBudget.Kind kind(){return n<100?DwfWorkBudget.Kind.RECIPE:DwfWorkBudget.Kind.TRANSPORT;}public boolean step(){seen[n]++;return true;}});}for(int t=0;t<10;t++)work.tick(128,1000000000,Map.of(DwfWorkBudget.Kind.RECIPE,32,DwfWorkBudget.Kind.TRANSPORT,32),false);for(int i=0;i<seen.length;i++)assertTrue(seen[i]>=3,"Starved machine "+i);assertEquals(640,Arrays.stream(seen).sum());}
 @Test void failedJobDoesNotLosePreviouslyServicedJobs(){var work=new DwfWorkBudget();int[]seen={0};work.add(new DwfWorkBudget.Job(){public DwfWorkBudget.Kind kind(){return DwfWorkBudget.Kind.RECIPE;}public boolean step(){seen[0]++;return true;}});work.add(new DwfWorkBudget.Job(){public DwfWorkBudget.Kind kind(){return DwfWorkBudget.Kind.RECIPE;}public boolean step(){throw new IllegalStateException("fixture");}});assertThrows(IllegalStateException.class,()->work.tick(8,1000000000,Map.of(),false));assertEquals(1,work.size());work.tick(1,1000000000,Map.of(),false);assertEquals(2,seen[0]);}
 @Test void backgroundLoadsShareUnusedCapacityAcrossFairRounds(){var work=new DwfWorkBudget();int[]seen={0,0};for(int i=0;i<2;i++){final int index=i;work.add(new DwfWorkBudget.Job(){public DwfWorkBudget.Kind kind(){return DwfWorkBudget.Kind.PERSISTENCE;}public boolean step(){seen[index]++;return true;}});}assertEquals(16,work.tick(16,1000000000,Map.of(),false).operations());assertArrayEquals(new int[]{8,8},seen);}
}
